sections.code:
https://id.gs1.org/01/08901234567895/10/BATCH99/21/SERIAL42?17=260101

// Broken down:
// host       = id.gs1.org (or brand.example.com)
// /01/       = AI 01 (GTIN)
// 08901234567895 = GTIN-14 padded
// /10/       = AI 10 (batch/lot)
// BATCH99    = lot ID
// /21/       = AI 21 (serial)
// SERIAL42   = unique serial
// ?17=       = AI 17 (expiry)
// 260101     = 2026-01-01 (YYMMDD)

class DigitalLink {
  final String host;
  final Map<String, String> pathAIs;   // ordered: primary + qualifiers
  final Map<String, String> queryAIs;  // data attributes

  DigitalLink({required this.host, required this.pathAIs, required this.queryAIs});

  /// Encode to URI
  Uri toUri({String scheme = 'https'}) {
    final buffer = StringBuffer('$scheme://$host');
    pathAIs.forEach((ai, value) => buffer.write('/$ai/$value'));
    if (queryAIs.isNotEmpty) {
      buffer.write('?');
      buffer.write(queryAIs.entries.map((e) => '${e.key}=${e.value}').join('&'));
    }
    return Uri.parse(buffer.toString());
  }

  /// Parse from URI — very simplified; production parser must handle AI-length rules.
  static DigitalLink? parse(String uri) {
    final u = Uri.tryParse(uri);
    if (u == null) return null;
    final segments = u.pathSegments;
    if (segments.length < 2 || segments.length.isOdd) return null;
    final path = <String, String>{};
    for (int i = 0; i < segments.length; i += 2) {
      path[segments[i]] = segments[i + 1];
    }
    return DigitalLink(
      host: u.host,
      pathAIs: path,
      queryAIs: u.queryParameters,
    );
  }
}

// Build
final dl = DigitalLink(
  host: 'id.gs1.org',
  pathAIs: {'01': '08901234567895', '10': 'BATCH99', '21': 'SERIAL42'},
  queryAIs: {'17': '260101'},
);
print(dl.toUri());  // https://id.gs1.org/01/08901234567895/10/BATCH99/21/SERIAL42?17=260101

// Parse
final parsed = DigitalLink.parse('https://id.gs1.org/01/08901234567895?17=260101');
print(parsed?.pathAIs['01']);   // 08901234567895

